CREATE TABLE IF NOT EXISTS inec_official_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_name text NOT NULL, source_url text NOT NULL UNIQUE, authority text NOT NULL, artifact_type text NOT NULL, retrieval_status text NOT NULL DEFAULT 'DISCOVERED', http_status integer, content_type text, byte_size bigint, sha256 text, storage_key text, verification_status text NOT NULL DEFAULT 'UNVERIFIED', notes text, retrieved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());